import { defineWorkflow, done, shape, step } from "../../../../packages/sdk/dist/index.js";

const nameInputShape = shape({ name: "string" });
const greetingOutputShape = shape({ greeting: "string" });

export const helloWorkflow = defineWorkflow({
  id: "hello",
  inputShape: nameInputShape,
  outputShape: greetingOutputShape,
  start(input) {
    return step(
      {
        id: "greet",
        input,
        outputShape: greetingOutputShape,
        run: ({ name }) => ({ greeting: `Hello, ${name}!` }),
      },
      (output) => done(output),
    );
  },
});

export const claudeWorkflow = defineWorkflow({
  id: "claude-greeting",
  inputShape: nameInputShape,
  outputShape: greetingOutputShape,
  agents: {
    writer: { size: "small" },
  },
  start(input) {
    return step(
      {
        id: "claude-greet",
        input,
        outputShape: greetingOutputShape,
        agent: "writer",
        prompt: ({ input }) =>
          `Create a concise, friendly greeting for ${input.name}. Write output as JSON with exactly this shape: {"greeting":"..."}.`,
      },
      (output) => done(output),
    );
  },
});

